$ErrorActionPreference='Stop'
$dir=Join-Path $env:TEMP 'hermes_fixfixfix'
New-Item -ItemType Directory -Force -Path $dir | Out-Null
$script=Join-Path $dir 'fixfixfix-permanent.ps1'
$b=''
[IO.File]::WriteAllBytes($script,[Convert]::FromBase64String($b))
$admin=([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
if(-not $admin){ Start-Process powershell.exe -Verb RunAs -ArgumentList @('-NoProfile','-ExecutionPolicy','Bypass','-File',$script); return }
& $script
